############################################################ # Load Macros ############################################################ loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PGlateximage.pl", "PCCmacros.pl", "contextInequalitySetBuilder.pl", "parserGraphTool.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context("Interval"); $interval = Interval("(1, inf)"); InequalitySetBuilder::UseVerticalSuchThat(); Context("InequalitySetBuilder-Only"); $setbuilder = Compute("{ x | x > 1}"); $gt = GraphTool("{interval, $interval}")->with( availableTools => ['IntervalTool', 'IncludeExcludePointTool'], numberLine => 1, xAxisLabel => 'x', bBox => [ -8, 8 ], ticksDistanceX => 1, minorTicksX => 0, useBracketEnds => 1, showInStatic => 0, showCoordinateHints => 0, ); $image_1 = createLaTeXImage(); $image_1->addToPreamble(latexImagePreamble()); $image_1->BEGIN_LATEX_IMAGE \begin{tikzpicture} \begin{axis}[numberline] \addplot[openinfiniteinterval] coordinates {(1,0) (10,0)}; \end{axis} \end{tikzpicture}
END_LATEX_IMAGE
############################################################ # Body ############################################################
BEGIN_PGML Solve the inequality [`\newcommand{\gt}{>}x-5\gt-4\text{.}`] Graph the solution set on a number line. State the solution set using both interval notation and set-builder notation.
[_]{$gt}{1}
[@KeyboardInstructions('In interval notation.')@]**
[_]{$interval}{12}
[@KeyboardInstructions('In set-builder notation. (If needed, type [|inf|]* or [|infinity|]* for [`\infty\text{,}`] [|>=|]* for [`\geq\text{,}`] and [|<=|]* for [`\leq\text{.}`])')@]**
[_]{$setbuilder}{12}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION To solve this inequality, we add [`5`] to each side.
[```\newcommand{\addright}[1]{{\highlight{{{}+#1}}}}\newcommand{\gt}{>}\newcommand{\amp}{&} \begin{aligned} x-5\amp\gt-4\\ x-5\addright{5}\amp\gt-4\addright{5}\\ x\amp\gt1 \end{aligned} ```]
Graphically, we represent this solution set as:
>> [@image(insertGraph($image_1), width=>600)@]* <<
Using interval notation, we write the solution set as [`(1, \infty)\text{.}`] Using set-builder notation, we write it as [`\newcommand{\gt}{>}\{x \mid x \gt 1\}\text{.}`]
We should check that some number less than [`1`] is _not_ a solution, that [`1`] itself is _not_ a solution, and that some number greater than [`1`] _is_ a solution.
[```\newcommand{\substitute}[1]{{\color{blue}{{#1}}}}\newcommand{\confirm}[1]{\stackrel{\checkmark}{#1}}\newcommand{\reject}[1]{\stackrel{\text{no}}{#1}}\newcommand{\wonder}[1]{\stackrel{\text{?}}{#1}}\newcommand{\gt}{>}\newcommand{\amp}{&} \begin{aligned} \amp\amp x-5\amp\gt-4\amp\amp\\ \substitute{0}-5\amp\wonder{\gt}-4\amp \substitute{1}-5\amp\wonder{\gt}-4\amp \substitute{10}-5\amp\wonder{\gt}-4\\ -5\amp\reject{\gt}-4\amp -4\amp\reject{\gt}-4\amp 5\amp\confirm{\gt}-4 \end{aligned} ```]
Everything worked out as expected, so our solution is reasonably checked.
END_PGML_SOLUTION
############################################################ # End Problem ############################################################
ENDDOCUMENT();

