############################################################ # Load Macros ############################################################ loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "contextForm.pl", "contextFiniteSolutionSets.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context("FiniteSolutionSets"); $solution = Formula("{6}");
############################################################ # Body ############################################################
BEGIN_PGML Solve for [`x`] in [`4 + 3(12 - x) = 12x - 5(2x - 2)\text{.}`]
[_]{$solution}{5}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION
[```\newcommand{\nextoperation}[1]{\mathord{\boxed{#1}}}\newcommand{\addright}[1]{{\highlight{{{}+#1}}}}\newcommand{\subtractright}[1]{{\highlight{{{}-#1}}}}\newcommand{\divideunder}[2]{\frac{#1}{{\highlight{{#2}}}}}\newcommand{\amp}{&} \begin{aligned} 4 + \nextoperation{3(12 - x)} \amp= 12x\nextoperation{{}-5(2x - 2)}\\ 4 + 36 - 3x \amp= 12x - 10x + 10\\ 40 - 3x \amp= 2x + 10\\ 40 - 3x\addright{3x} \amp= 2x + 10\addright{3x}\\ 40 \amp= 5x + 10\\ 40\subtractright{10} \amp= 5x + 10\subtractright{10}\\ 30 \amp= 5x\\ \divideunder{30}{5}\amp=\divideunder{5x}{5}\\ 6\amp=x \end{aligned} ```]
Checking the solution [`6\text{:}`]
[```\newcommand{\substitute}[1]{{\color{blue}{{#1}}}}\newcommand{\confirm}[1]{\stackrel{\checkmark}{#1}}\newcommand{\wonder}[1]{\stackrel{\text{?}}{#1}}\newcommand{\amp}{&} \begin{aligned} 4 + 3(12 - x) \amp= 12x - 5(2x - 2)\\ 4 + 3(12 - \substitute{6}) \amp\wonder{=} 12\substitute{(6)} - 5(2\substitute{(6)} - 2)\\ 4 + 3(6) \amp\wonder{=} 72 - 5(12 - 2)\\ 4 + 18 \amp\wonder{=} 72 - 5(10)\\ 22 \amp\confirm{=} 72 - 50 \end{aligned} ```]
Therefore the solution is [`6`] and the solution set is [`\{6\}\text{.}`]
END_PGML_SOLUTION
############################################################ # End Problem ############################################################
ENDDOCUMENT();

