############################################################ # Load Macros ############################################################ loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "contextForm.pl", "contextFiniteSolutionSets.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context("FiniteSolutionSets"); $solution = String("no real solutions")->cmp(typeMatch => Formula("{1}"));
############################################################ # Body ############################################################
BEGIN_PGML Solve for [`a`] in [`\frac{2}{3}(a+1)-\frac{5}{6}=\frac{2}{3}a\text{.}`]
[_]{$solution}{16}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION We recall the technique from Section[$NBSP]*3 where we clear denominators by multiplying each side of the equation by the least common denominator. Here, we will multiply each side by [`6\text{.}`] After that, we'll be able to simplify each side of the equation and continue:
[```\newcommand{\subtractright}[1]{{\highlight{{{}-#1}}}}\newcommand{\multiplyleft}[2][\cdot]{{\highlight{{#2#1{}}}}}\newcommand{\amp}{&} \begin{aligned} \frac{2}{3}(a+1)-\frac{5}{6}\amp=\frac{2}{3}a\\ \multiplyleft{6}\left(\frac{2}{3}(a+1)-\frac{5}{6}\right)\amp=\multiplyleft{6}\frac{2}{3}a\\ \multiplyleft{6}\frac{2}{3}(a+1)-\multiplyleft{6}\frac{5}{6}\amp=\multiplyleft{6}\frac{2}{3}a\\ 4(a+1)-5\amp=4a\\ 4a+4-5\amp=4a\\ 4a-1\amp=4a\\ 4a-1\subtractright{4a}\amp=4a\subtractright{4a}\\ -1\amp=0 \end{aligned} ```]
The statement [`-1=0`] is unambiguously false, so the equation has no solution.
END_PGML_SOLUTION
############################################################ # End Problem ############################################################
ENDDOCUMENT();

