############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context()->variables->add(y => 'Real'); @y = (-2,-7); @x = (5,-10); Context()->flags->set(reduceConstants => 0); $f = Compute("-(3/5)x + 1"); @right = map{$f->substitute(x => Formula($x[$_]))}(0,1); @d = ( DropDown(['It is included in the graph.','It is not included in the graph.'], 0, showInStatic => 0), DropDown(['It is included in the graph.','It is not included in the graph.'], 1, showInStatic => 0), );
############################################################ # Body ############################################################
BEGIN_PGML Decide whether [`(5,-2)`] and [`(-10,-7)`] are on the graph of the equation [`y=-\frac{3}{5}x+1\text{.}`]
[@KeyboardInstructions('At [`(5,-2)\text{:}`]')@]**
>> [@DataTable( [ [[PGML('[`y`]'), rowbottom => '2', midrule => '1',], PGML('[`=`]'), PGML('[`-\frac{3}{5}x+1`]'), ], [PGML('[_]{$y[0]}{2}'), PGML('[`\wonder{=}`]'), PGML('[_]{$right[0]}{10}'), ], ], align => 'rcl', valign => 'middle', );@]* <<
[_]{$d[0]}{5}
[@KeyboardInstructions('At [`(-10,-7)\text{:}`]')@]**
>> [@DataTable( [ [[PGML('[`y`]'), rowbottom => '2', midrule => '1',], PGML('[`=`]'), PGML('[`-\frac{3}{5}x+1`]'), ], [PGML('[_]{$y[1]}{2}'), PGML('[`\wonder{=}`]'), PGML('[_]{$right[1]}{10}'), ], ], align => 'rcl', valign => 'middle', );@]* <<
[_]{$d[0]}{5}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION If the point [`(5,-2)`] is on [`y=-\frac{3}{5}x+1\text{,}`] once we substitute [`x=5`] and [`y=-2`] into the line's equation, the equation should be true. Let's try:
[```\newcommand{\confirm}[1]{\stackrel{\checkmark}{#1}}\newcommand{\wonder}[1]{\stackrel{\text{?}}{#1}}\newcommand{\amp}{&} \begin{aligned} y\amp=-\frac{3}{5}x+1\\ -2\amp\wonder{=}-\frac{3}{5}(5)+1\\ -2\amp\confirm{=} -3+1 \end{aligned} ```]
Because this last equation is true, we can say that [`(5,-2)`] is on the graph of [`y=-\frac{3}{5}x+1\text{.}`]
However if we substitute [`x=-10`] and [`y=-7`] into the equation, it leads to [`-7=7\text{,}`] which is false. This tells us that [`(-10,-7)`] is _not_ on the graph.
END_PGML_SOLUTION
############################################################ # End Problem ############################################################
ENDDOCUMENT();

