############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context('Numeric'); @eq=( '2.7x+3.4y=-82', 'y=\frac{2}{7}(x-3)+\frac{1}{10}', '12x-3=y+2', 'y=x^2+5', 'x-y=10', 'y=4x+1', ); $forms=['slope-intercept', 'point-slope', 'standard', 'other linear', 'not linear']; @ans=( DropDown($forms,2, showInStatic => 0), DropDown($forms,1, showInStatic => 0), DropDown($forms,3, showInStatic => 0), DropDown($forms,4, showInStatic => 0), DropDown($forms,2, showInStatic => 0), DropDown($forms,0, showInStatic => 0), );
############################################################ # Body ############################################################
BEGIN_PGML For each of the following equations, identify what form they are in: slope-intercept, point-slope, standard, other linear, or not linear.
[`[$eq[0]]`] [_]{$ans[0]}{5}
[`[$eq[1]]`] [_]{$ans[1]}{5}
[`[$eq[2]]`] [_]{$ans[2]}{5}
[`[$eq[3]]`] [_]{$ans[3]}{5}
[`[$eq[4]]`] [_]{$ans[4]}{5}
[`[$eq[5]]`] [_]{$ans[5]}{5}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION [`[$eq[0]]`] is in standard form, with [`A=2.7\text{,}`] [`B=3.4\text{,}`] and [`C=-82\text{.}`]
[`[$eq[1]]`] is in point-slope form, with slope [`\frac{2}{7}\text{,}`] and passing through [`\left(3,\frac{1}{10}\right)\text{.}`]
[`[$eq[2]]`] is linear, but not in any of the forms we have studied. Using algebra, you can rearrange it to read [`y=12x-5\text{.}`]
[`[$eq[3]]`] is not linear. The exponent on [`x`] is a dead giveaway.
[`[$eq[4]]`] is in standard form, with [`A=1\text{,}`] [`B=-1\text{,}`] and [`C=10\text{.}`]
[`[$eq[5]]`] is in slope-intercept form, with slope [`4`] and [`y`]-intercept at [`(0,1)\text{.}`]
END_PGML_SOLUTION
