############################################################ # PG Setup Code ############################################################ Context("Point"); Context()->flags->set(reduceConstants=>0); $xi=Compute("(4,0)"); $yi=Compute("(0,-6)"); $gt = GraphTool("{line, solid, $xi, $yi}")->with( bBox => [-11, 11, 11, -11], showInStatic => 0, ); $image_1 = createLaTeXImage(); $image_1->addToPreamble(latexImagePreamble()); $image_1->BEGIN_LATEX_IMAGE \begin{tikzpicture} \begin{axis}[ width=0.47\orccaprintwidth, ] \addplot+[domain=-0.666:7]{-6+1.5*x}; \end{axis} \end{tikzpicture}
END_LATEX_IMAGE
############################################################ # Body ############################################################
BEGIN_PGML Consider the line with equation [`3x-2y=12\text{.}`] Graph the line by first finding its [`x`]\- and [`y`]-intercepts.
[@KeyboardInstructions('Enter the [`x`]-intercept here.')@]**
[_]{$xi}{5}
[@KeyboardInstructions('Enter the [`y`]-intercept here.')@]**
[_]{$yi}{5}
[_]{$gt}{1}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION To find the [`x`]-intercept:
[```\newcommand{\substitute}[1]{{\color{blue}{{#1}}}}\newcommand{\amp}{&} \begin{aligned} 3x-2y\amp=12\\ 3x-2(\substitute{0})\amp=12\\ 3x\amp=12\\ x\amp=4 \end{aligned} ```]
So the [`x`]-intercept is at [`\left(4,0\right)\text{.}`]
To find the [`y`]-intercept:
[```\newcommand{\substitute}[1]{{\color{blue}{{#1}}}}\newcommand{\amp}{&} \begin{aligned} 3x-2y\amp=12\\ 3(\substitute{0})-2y\amp=12\\ -2y\amp=12\\ y\amp=6\ldots \end{aligned} ```]
So the [`y`]-intercept is at about [`(0,-6)\text{.}`]
So the graph is:
>> [@image(insertGraph($image_1), width=>282)@]* <<
END_PGML_SOLUTION
