TEXT(beginproblem());

############################################################
# PG Setup Code
############################################################
($x, $y) = random_subset(2, 2..9);
$C = lcm($x,$y);
$A = $C/$x;
$B = $C/$y;
Context()->variables->add(y => 'Real');
Context()->noreduce('(-x)-y', '(-x)+y');
$left = Formula("$A x + $B y");
$right = Formula("$C");
Context("Point");
$xi = Point($x,0);
$yi = Point(0,$y);
Context("Fraction");
$m = Fraction(-$x/$y);

############################################################
# Body
############################################################

BEGIN_PGML
Find both intercepts and the slope of the line.

[`[$left]=[$right]`]

