      ytick={-10,-5,5,10},
      minor xtick={-10,...,10},
      minor ytick={-10,...,10},
      width=0.47\orccaprintwidth,
    ]
    \addplot+[domain=$l:$r] {$f};
    \addplot[soliddot] coordinates {$xi $yi};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

############################################################
# Body
############################################################

BEGIN_PGML
Use whatever method you think best to plot the line.

