      width=0.47\orccaprintwidth,
    ]
    \addplot[firstcurve,-,domain=-10:10]{$f[0]};
    \addplot[secondcurve,-,domain=-10:10]{$f[1]};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

