[```\newcommand{\multiplyleft}[2][\cdot]{{\highlight{{#2#1{}}}}}\newcommand{\amp}{&} \begin{aligned} \amp\left\{\begin{alignedat}{4}5x\amp+{}\amp 6y \amp={}\amp -7 \\\multiplyleft{-3}(4x\amp+{}\amp 2y) \amp={}\amp\multiplyleft{-3}(-1)\end{alignedat}\right.\\ \\ \amp\left\{\underline{\begin{alignedat}{4}5x\amp+{}\amp 6y \amp={}\amp -7 \\-12x\amp-{}\amp 6y \amp={}\amp 3\end{alignedat}} \right.\\ \amp\phantom{\Bigg\{}\begin{alignedat}{4}{-7}x\amp\phantom{{}+{}}\amp\phantom{6y}\amp=-4\\\phantom{-12x}\amp\amp x\amp=\frac{4}{7}\end{alignedat} \end{aligned} ```]
