$f[0] = Formula("$left[0] = $right[0]");
$left[1] = Formula("$B[1] $Y")->reduce;
$right[1] = Formula("-$A[1] $X + $C[1]")->reduce;
$f[1] = Formula("$left[1] = $right[1]");
$xis = Formula("$X = $x");
$yis = Formula("$Y = $y");
