############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context("LimitedFraction"); @f=(Fraction(10,21),Fraction(20,1),Fraction(-28,15),Fraction(-14,9));
############################################################ # Body ############################################################
BEGIN_PGML Simplify these fraction products.
END_PGML
############################################################ # Scaffold ############################################################ Scaffold::Begin(numbered => 1,is_open => "correct_or_first_incorrect",can_open => always,);
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML [`\dfrac{1}{3}\cdot\dfrac{10}{7}=`][_]{$f[0]}{10}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION Multiplying numerators gives [`10\text{,}`] and multiplying denominators gives [`21\text{.}`] The answer is [`\frac{10}{21}\text{.}`]
END_PGML_SOLUTION
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML [`\dfrac{12}{3}\cdot\dfrac{15}{3}=`][_]{$f[1]}{10}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION Before we multiply fractions, note that [`\frac{12}{3}`] reduces to [`4\text{,}`] and [`\frac{15}{3}`] reduces to [`5\text{.}`] So we just have [`4\cdot5=20\text{.}`]
END_PGML_SOLUTION
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML [`-\dfrac{14}{5}\cdot\dfrac{2}{3}=`][_]{$f[2]}{10}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION Multiplying numerators gives [`28\text{,}`] and multiplying denominators gives [`15\text{.}`] The result should be negative, so the answer is [`-\frac{28}{15}\text{.}`]
END_PGML_SOLUTION
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML [`\dfrac{70}{27}\cdot\dfrac{12}{-20}=`][_]{$f[3]}{10}
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION Before we multiply fractions, note that [`\frac{12}{-20}`] reduces to [`\frac{-3}{5}\text{.}`] So we have [`\frac{70}{27}\cdot\frac{-3}{5}\text{.}`] Both the numerator of the first fraction and denominator of the second fraction are divisible by [`5\text{,}`] so it helps to reduce both fractions accordingly and get [`\frac{14}{27}\cdot\frac{-3}{1}\text{.}`] Both the denominator of the first fraction and numerator of the second fraction are divisible by [`3\text{,}`] so it helps to reduce both fractions accordingly and get [`\frac{14}{9}\cdot\frac{-1}{1}\text{.}`] Now we are just multiplying [`\frac{14}{9}`] by [`-1\text{,}`] so the result is [`\frac{-14}{9}\text{.}`]
END_PGML_SOLUTION
Section::End();
Scaffold::End();
############################################################ # End Problem ############################################################
ENDDOCUMENT();

