p.m:
\displaystyle{\begin{aligned}
    30\cdot\left( -{\frac{3}{10}} \right)
    \amp =\frac{30}{1} \cdot \left(-{\frac{3}{10}}\right) \amp \hbox{We can divide both the first numerator and the second denominator by 10.}\\
    \amp =\frac{3}{1} \cdot \left(-{\frac{3}{1}}\right)\\
    \amp ={-9}
    \end{aligned}}

\displaystyle{\begin{aligned}
    35\cdot\left( -{\frac{4}{7}} \right)
    \amp =\frac{35}{1} \cdot \left(-{\frac{4}{7}}\right) \amp \hbox{We can divide both the first numerator and the second denominator by 7.}\\
    \amp =\frac{5}{1} \cdot \left(-{\frac{4}{1}}\right)\\
    \amp ={-20}
    \end{aligned}}

\displaystyle{\begin{aligned}[t]
    \frac{5}{8} \div \left(-\frac{3}{20}\right)
        \amp = \frac{5}{8} \cdot \left(-\frac{20}{3}\right) \amp \hbox{We can divide the first denominator and the second numerator by 4.}\\
        \amp = \frac{5}{2 }\cdot\left(-\frac{5}{3}\right) \\
        \amp = -\frac{25}{6}
\end{aligned}
    }

\displaystyle{\begin{aligned}[t]
    \frac{1}{6} \div \left(-\frac{7}{10}\right)
        \amp = \frac{1}{6} \cdot \left(-\frac{10}{7}\right) \amp \hbox{We can divide the first denominator and the second numerator by 2.}\\
        \amp = \frac{1}{3 }\cdot\left(-\frac{5}{7}\right) \\
        \amp = -\frac{5}{21}
\end{aligned}
    }

\displaystyle{\begin{aligned}
   \left(-\frac{15}{7}\right) \div (-10)
       \amp = \frac{15}{7} \div 10 \\
       \amp = \frac{15}{7} \div \frac{10}{1} \\
       \amp = \frac{15}{7} \cdot \frac{1}{10} \amp \hbox{We can simplify by dividing 15 and 10 by 5, making the numbers smaller.}\\
       \amp = \frac{3}{7}\cdot \frac{1}{2} \\
       \amp = \frac{3 \cdot 1}{7 \cdot 2} \\
       \amp = \frac{3}{14}
\end{aligned}
    }

\displaystyle{\begin{aligned}
   \left(-\frac{15}{2}\right) \div (-10)
       \amp = \frac{15}{2} \div 10 \\
       \amp = \frac{15}{2} \div \frac{10}{1} \\
       \amp = \frac{15}{2} \cdot \frac{1}{10} \amp \hbox{We can simplify by dividing 15 and 10 by 5, making the numbers smaller.}\\
       \amp = \frac{3}{2}\cdot \frac{1}{2} \\
       \amp = \frac{3 \cdot 1}{2 \cdot 2} \\
       \amp = \frac{3}{4}
\end{aligned}
    }

\displaystyle{\begin{aligned}
   15\div \frac{5}{4} 
       \amp = \frac{15}{1} \div \frac{5}{4} \\
       \amp = \frac{15}{1} \cdot \frac{4}{5} \amp \hbox{We can divide 15 and 5 by 5 and made those two values smaller.}\\
       \amp = \frac{3}{1}\cdot\frac{4}{1} \\
       \amp = \frac{3\cdot4}{1 \cdot 1} \\
       \amp = 12
\end{aligned}
    }

\displaystyle{\begin{aligned}
   25\div \frac{5}{4} 
       \amp = \frac{25}{1} \div \frac{5}{4} \\
       \amp = \frac{25}{1} \cdot \frac{4}{5} \amp \hbox{We can divide 25 and 5 by 5 and made those two values smaller.}\\
       \amp = \frac{5}{1}\cdot\frac{4}{1} \\
       \amp = \frac{5\cdot4}{1 \cdot 1} \\
       \amp = 20
\end{aligned}
    }

\displaystyle{\begin{aligned}
