[```\newcommand{\highlight}[1]{\mathchoice{\colorbox{lightsapphire}{$\displaystyle #1$}}{\colorbox{lightsapphire}{$\textstyle #1$}}{\colorbox{lightsapphire}{$\scriptstyle #1$}}{\colorbox{lightsapphire}{$\scriptscriptstyle #1$}}}\newcommand{\nextoperation}[1]{\mathord{\boxed{#1}}}\newcommand{\amp}{&} \begin{aligned} 24\div(15\div 3+1) +2\amp= 24\div(\nextoperation{15\div 3}+1) +2\\ \amp=24\div(\nextoperation{\highlight{5}+1}) +2\\ \amp=\nextoperation{24\div \highlight{6}}+2\\ \amp=\highlight{4}+2\\ \amp=\highlight{6} \end{aligned} ```]
END_PGML_SOLUTION
