  $a = $exponent + $b;
}
elsif ($op[0] eq '*') {
  $b = 2;
  $a = $exponent/2;
}
elsif ($op[$i] eq '/') {
  $b = random(2,9,1);
  $a = $exponent * $b;
}
if (list_random(0,1)) {
